import{_ as t,o,c as l,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"3.3 User & Client Profile (4 FRs)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/02-profile/README.md","filePath":"feature/srs/02-profile/README.md"}'),d={name:"feature/srs/02-profile/README.md"};function i(c,e,a,s,n,p){return o(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-3-user-client-profile-4-frs" tabindex="-1">3.3 User &amp; Client Profile (4 FRs) <a class="header-anchor" href="#_3-3-user-client-profile-4-frs" aria-label="Permalink to &quot;3.3 User &amp; Client Profile (4 FRs)&quot;">​</a></h1><p>&gt; <strong>Navigation:</strong> <a href="./../../README.html">← Feature Master Index</a> · <a href="./../README.html">← SRS 141 FRs Index</a> · <a href="./../../../ba/02-authentication-profile.html">BA Domain Spec</a> · <a href="./../../../ba/use-cases/01-authentication-profile.html">Use Cases</a> · <a href="./../../modules/README.html">Module Specs Index</a> · <a href="./../../../rule/feature-workflow.html">Workflow Rule</a></p><p>Canonical specification, technical implementation plan, task breakdown, and unit/acceptance test verification suite for <strong>3.3 User &amp; Client Profile</strong> (<code>3.3.1 – 3.3.4</code>, <strong>4 Atomic CRUD Functional Requirements</strong>).</p><hr><h2 id="_1-domain-architecture-overview" tabindex="-1">1. Domain Architecture Overview <a class="header-anchor" href="#_1-domain-architecture-overview" aria-label="Permalink to &quot;1. Domain Architecture Overview&quot;">​</a></h2><p>Domain <code>3.3</code> separates <strong>personal identity (<code>User</code>)</strong> from <strong>reusable brand representation (<code>ClientProfile</code>)</strong> so a single user account can collaborate across multiple Agencies and Workspaces without duplicating accounts:</p><ul><li><strong>Personal User Profile (<code>3.3.1</code>, <code>3.3.2</code>):</strong><ul><li><strong>Backend (<code>brandhub-business-service</code>):</strong> <code>UserController</code> (<code>GET /api/v1/users/me</code>, <code>PUT /api/v1/users/me</code>, <code>POST /api/v1/users/me/avatar</code>, <code>POST /api/v1/users/me/banner</code>, <code>GET /api/v1/users/lookup</code>) → <code>UserServiceImpl</code> + <code>ProfileMatchingController</code> (<code>GET /api/v1/users/me/completeness</code>).</li><li><strong>Storage &amp; Schema:</strong> PostgreSQL <code>users</code> (<code>full_name</code>, <code>phone</code>, <code>avatar_url</code>, <code>banner_url</code>, <code>professional_title</code>, <code>bio</code>, <code>portfolio_urls</code>, <code>working_language</code>, <code>preferences</code> JSONB storing <code>timezone</code> and <code>notificationPreferences</code>), <code>user_system_roles</code>, and AWS S3 (<code>S3FileStorageServiceImpl</code>) for validated image uploads (max 5 MB, <code>image/*</code> magic-byte &amp; MIME validation via <code>ImageValidator</code>).</li></ul></li><li><strong>User-Owned Client Profiles (Multi-Brand Representation) (<code>3.3.3</code>, <code>3.3.4</code>):</strong><ul><li><strong>Backend (<code>brandhub-business-service</code>):</strong> <code>ClientProfileController</code> (<code>GET /api/v1/client-profile/mine</code>, <code>POST /api/v1/client-profile</code>, <code>POST /api/v1/client-profile/logo</code>, <code>GET /api/v1/client-profile/{profileId}</code>, <code>PUT /api/v1/client-profile/{profileId}</code>, <code>POST /api/v1/client-profile/{profileId}/logo</code>, <code>DELETE /api/v1/client-profile/{profileId}</code>) → <code>ClientProfileServiceImpl</code> + <code>ClientProfileRepository</code>.</li><li><strong>Decoupled Ownership Model (V2 Architecture):</strong> <code>client_profiles</code> belongs strictly to <code>user_id</code> (no <code>agency_id</code> column). One <code>Client</code> user can maintain multiple brand profiles (e.g., distinct brands or subsidiaries) and attach any profile to any Workspace via <code>workspace_members.client_profile_id</code>. Deletion is guarded by <code>409 CLIENT_PROFILE_IN_USE</code> while linked to an active Workspace membership.</li></ul></li><li><strong>Client Surfaces (<code>brandhub-web</code> &amp; <code>brandhub-mobile-app</code>):</strong><ul><li><strong>Web (<code>brandhub-web</code>):</strong> <code>src/pages/profile/index.tsx</code> (<code>ProfileViewDetails</code>, <code>ProfileEditForm</code>, <code>AvatarUploadModal</code>, <code>LinkPhoneModal</code>, <code>CompletenessCard</code>), <code>src/pages/workspace/client-profile.tsx</code>, <code>src/pages/workspace/clients.tsx</code>, <code>src/services/{userService,clientProfileService}.ts</code>.</li><li><strong>Mobile (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/settings/AccountSettingsScreen.tsx</code>, <code>src/screens/more/{ClientsScreen,ClientProfileScreen}.tsx</code>, <code>src/services/{userService,clientProfileService}.ts</code>.</li></ul></li></ul><hr><h2 id="_2-functional-requirements-matrix" tabindex="-1">2. Functional Requirements Matrix <a class="header-anchor" href="#_2-functional-requirements-matrix" aria-label="Permalink to &quot;2. Functional Requirements Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">FR ID</th><th style="text-align:left;">UC ID</th><th style="text-align:left;">Function Name</th><th style="text-align:left;">Canonical Roles</th><th style="text-align:left;">Status</th><th style="text-align:left;">Feature Artefacts (<code>spec → plan → task → test</code>)</th></tr></thead><tbody><tr><td style="text-align:left;"><code>3.3.1</code></td><td style="text-align:left;"><code>UC-010</code></td><td style="text-align:left;"><strong>View User Profile</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client, Admin</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-3-1-view-user-profile/spec.html">Spec</a> · <a href="./3-3-1-view-user-profile/plan.html">Plan</a> · <a href="./3-3-1-view-user-profile/task.html">Task</a> · <a href="./3-3-1-view-user-profile/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.3.2</code></td><td style="text-align:left;"><code>UC-011</code></td><td style="text-align:left;"><strong>Update User Profile</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client, Admin</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-3-2-update-user-profile/spec.html">Spec</a> · <a href="./3-3-2-update-user-profile/plan.html">Plan</a> · <a href="./3-3-2-update-user-profile/task.html">Task</a> · <a href="./3-3-2-update-user-profile/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.3.3</code></td><td style="text-align:left;"><code>UC-012</code></td><td style="text-align:left;"><strong>View Client Profile</strong></td><td style="text-align:left;"><code>Owner, Manager, Client</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-3-3-view-client-profile/spec.html">Spec</a> · <a href="./3-3-3-view-client-profile/plan.html">Plan</a> · <a href="./3-3-3-view-client-profile/task.html">Task</a> · <a href="./3-3-3-view-client-profile/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.3.4</code></td><td style="text-align:left;"><code>UC-013</code></td><td style="text-align:left;"><strong>Update Client Profile</strong></td><td style="text-align:left;"><code>Owner, Manager, Client</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-3-4-update-client-profile/spec.html">Spec</a> · <a href="./3-3-4-update-client-profile/plan.html">Plan</a> · <a href="./3-3-4-update-client-profile/task.html">Task</a> · <a href="./3-3-4-update-client-profile/test.html">Test</a></td></tr></tbody></table><hr><h2 id="_3-core-business-rules-ownership-invariants" tabindex="-1">3. Core Business Rules &amp; Ownership Invariants <a class="header-anchor" href="#_3-core-business-rules-ownership-invariants" aria-label="Permalink to &quot;3. Core Business Rules &amp; Ownership Invariants&quot;">​</a></h2><ul><li><strong><code>BR-11</code> (Immutable Principal Email &amp; Validated Media):</strong> Personal profile updates derive identity strictly from <code>@AuthenticationPrincipal</code> (<code>/api/v1/users/me</code>), prohibit email mutation, and enforce <code>image/*</code> MIME + 5 MB size limits on avatar/banner uploads.</li><li><strong><code>BR-13</code> (User-Owned Reusable Client Profiles):</strong> Each <code>ClientProfile</code> is owned by one <code>User</code> (<code>user_id</code>) and reusable across multiple Workspaces and Agencies via <code>workspace_members.client_profile_id</code>.</li><li><strong><code>BR-14</code> (Ownership &amp; Active-Link Deletion Guard):</strong> Only the owning user may update or delete a <code>ClientProfile</code> (<code>403 CLIENT_PROFILE_NOT_OWNED</code>), and deletion is rejected (<code>409 CLIENT_PROFILE_IN_USE</code>) while any active <code>workspace_members</code> record references that profile.</li></ul><h2 id="_4-cross-references" tabindex="-1">4. Cross-References <a class="header-anchor" href="#_4-cross-references" aria-label="Permalink to &quot;4. Cross-References&quot;">​</a></h2><ul><li><strong>BA Domain Specification:</strong> <a href="./../../../ba/02-authentication-profile.html">02-authentication-profile.md</a></li><li><strong>BA System Overview:</strong> <a href="./../../../ba/README.html">BA Overview</a></li><li><strong>Consolidated Feature Modules:</strong> <a href="./../../modules/README.html">Module Specs Index</a></li></ul><hr><h2 id="_5-endpoint-persistence-reference" tabindex="-1">5. Endpoint &amp; Persistence Reference <a class="header-anchor" href="#_5-endpoint-persistence-reference" aria-label="Permalink to &quot;5. Endpoint &amp; Persistence Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">FR ID</th><th style="text-align:left;">Primary HTTP Endpoints</th><th style="text-align:left;">Backend Controller &amp; Service</th><th style="text-align:left;">Primary Storage</th><th style="text-align:left;">Web &amp; Mobile Surfaces</th></tr></thead><tbody><tr><td style="text-align:left;"><code>3.3.1</code></td><td style="text-align:left;"><code>GET /api/v1/users/me</code>&lt;br&gt;<code>GET /api/v1/users/me/completeness</code></td><td style="text-align:left;"><code>UserController</code> -&gt; <code>UserServiceImpl</code>&lt;br&gt;<code>ProfileMatchingController</code> -&gt; <code>CompletenessService</code></td><td style="text-align:left;">PostgreSQL <code>users</code>, <code>user_system_roles</code>, <code>workspace_members</code></td><td style="text-align:left;">Web: <code>/profile</code> (<code>ProfileViewDetails</code>)&lt;br&gt;Mobile: <code>AccountSettingsScreen</code></td></tr><tr><td style="text-align:left;"><code>3.3.2</code></td><td style="text-align:left;"><code>PUT /api/v1/users/me</code>&lt;br&gt;<code>POST /api/v1/users/me/avatar</code>&lt;br&gt;<code>POST /api/v1/users/me/banner</code></td><td style="text-align:left;"><code>UserController</code> -&gt; <code>UserServiceImpl</code>, <code>S3FileStorageServiceImpl</code>, <code>ImageValidator</code></td><td style="text-align:left;">PostgreSQL <code>users</code> (<code>preferences</code> JSONB) + AWS S3 (<code>avatars/</code>, <code>banners/</code>)</td><td style="text-align:left;">Web: <code>/profile</code> (<code>ProfileEditForm</code>, <code>AvatarUploadModal</code>)&lt;br&gt;Mobile: <code>AccountSettingsScreen</code></td></tr><tr><td style="text-align:left;"><code>3.3.3</code></td><td style="text-align:left;"><code>GET /api/v1/client-profile/mine</code>&lt;br&gt;<code>GET /api/v1/client-profile/{profileId}</code>&lt;br&gt;<code>GET /api/v1/workspaces/{workspaceId}/members</code></td><td style="text-align:left;"><code>ClientProfileController</code> -&gt; <code>ClientProfileServiceImpl</code>&lt;br&gt;<code>WorkspaceController</code> -&gt; <code>WorkspaceServiceImpl</code></td><td style="text-align:left;">PostgreSQL <code>client_profiles</code> (<code>user_id</code> FK), <code>workspace_members</code> (<code>client_profile_id</code>)</td><td style="text-align:left;">Web: <code>/client-profiles</code>, <code>/workspaces/:id/clients</code>&lt;br&gt;Mobile: <code>ClientsScreen</code>, <code>ClientProfileScreen</code></td></tr><tr><td style="text-align:left;"><code>3.3.4</code></td><td style="text-align:left;"><code>POST /api/v1/client-profile</code>&lt;br&gt;<code>PUT /api/v1/client-profile/{profileId}</code>&lt;br&gt;<code>POST /api/v1/client-profile/{profileId}/logo</code>&lt;br&gt;<code>DELETE /api/v1/client-profile/{profileId}</code></td><td style="text-align:left;"><code>ClientProfileController</code> -&gt; <code>ClientProfileServiceImpl</code>, <code>S3FileStorageServiceImpl</code></td><td style="text-align:left;">PostgreSQL <code>client_profiles</code>, <code>workspace_members</code> + AWS S3 (<code>client-logos/</code>)</td><td style="text-align:left;">Web: <code>/client-profiles</code>&lt;br&gt;Mobile: <code>ClientProfileScreen</code></td></tr></tbody></table>',18)])])}const m=t(d,[["render",i]]);export{g as __pageData,m as default};
